import java.util.List;
import java.util.Map;
import org.springframework.stereotype.Component;

// NotificationType và interface NotificationService (với supportedType())
// đã khai báo ở phần @Qualifier/@Profile phía trên — xem day15-blk-7.
@Component
class NotificationSenderFactory {

    private final Map<NotificationType, NotificationService> senders;

    // Spring tiêm TOÀN BỘ bean NotificationService vào một List (không phải
    // từng bean riêng lẻ qua tên) — mỗi sender tự khai báo NotificationType
    // của mình qua supportedType(), nên Factory không cần biết trước tên
    // bean hay số lượng loại sender đang tồn tại.
    NotificationSenderFactory(List<NotificationService> senders) {
        // TODO: derive this.senders từ tham số senders — với mỗi phần tử,
        // dùng sender.supportedType() làm key và chính sender đó làm value
        // (gợi ý: senders.stream().collect(Collectors.toMap(
        // NotificationService::supportedType, Function.identity()))).
        // KHÔNG được hardcode từng NotificationType trong constructor —
        // nếu hardcode, thêm sender mới lại phải sửa Factory, đúng lỗi mà
        // bài đã ghi nhận và sửa ở đây (xem day15-blk-10).
        this.senders = null;
    }

    NotificationService senderFor(NotificationType type) {
        NotificationService sender = senders.get(type);
        if (sender == null) {
            throw new IllegalArgumentException("Không có sender cho: " + type);
        }
        return sender;
    }
}

class NotificationSendException extends Exception {
    NotificationSendException(String message, Throwable cause) {
        super(message, cause);
    }
}

class RetryingNotificationSender {

    private static final int MAX_ATTEMPTS = 3;

    private final NotificationService delegate;

    RetryingNotificationSender(NotificationService delegate) {
        this.delegate = delegate;
    }

    void sendWithRetry(String recipient, String message) {
        for (int attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
            try {
                delegate.send(recipient, message);
                return;
            } catch (RuntimeException sendFailed) {
                // TODO: nếu attempt == MAX_ATTEMPTS, ném một exception nghiệp
                // vụ (terminal) để tầng gọi biết gửi đã thất bại hẳn — KHÔNG
                // nuốt lỗi âm thầm và KHÔNG thử lại vô hạn (xem commonMistakes).

                // TODO: nếu chưa phải lần cuối, chờ một khoảng backoff tăng
                // dần trước khi thử lại (ví dụ nhân đôi delay mỗi lần thử).
                // Cẩn thận nếu dùng Thread.sleep: đây là luồng xử lý request,
                // sleep trực tiếp sẽ chặn luồng đó tới khi hết retry.
            }
        }
    }
}

